class PersistenceDiagram(NodeData):
    def __init__(self, diagram):
        self.diagram = diagram

    def __getstate__(self):
        state = self.__dict__.copy()
        state["diagram"] = None
        return state

    def save(self, dirname):
        super().save(dirname)
        SaveData(f"{dirname}/diagram.pvtu", self.diagram)

    @classmethod
    def load(cls, dirname):
        base = super().load(dirname)

        diagram = XMLPartitionedUnstructuredGridReader(FileName=[f"{dirname}/diagram.pvtu"])
        diagram.CellArrayStatus = ['PairIdentifier', 'PairType', 'Persistence', 'Birth', 'IsFinite']
        diagram.PointArrayStatus = ['ttkVertexScalarField', 'CriticalType', 'Coordinates']
        diagram.TimeArray = 'None'

        base.diagram = diagram
        return base

    @classmethod
    def get_mcp_name(cls):
        return "persistence_diagram"

    @classmethod
    def chat_description(cls):
        return "persistence diagram"


class PersistenceDiagramEmbedding(NodeData):

    def __init__(self, diagram_with_ids, lut, ball_radius, tube_radius):
        self.diagram = diagram_with_ids
        self.lut = lut
        self.ball_radius = ball_radius
        self.tube_radius = tube_radius

    def __getstate__(self):
        state = self.__dict__.copy()
        state["diagram"] = None
        return state

    def save(self, dirname):
        super().save(dirname)
        SaveData(f"{dirname}/diagram.pvtu", self.diagram)

    @classmethod
    def load(cls, dirname):
        base = super().load(dirname)

        diagram = XMLPartitionedUnstructuredGridReader(FileName=[f"{dirname}/diagram.pvtu"])
        diagram.CellArrayStatus = ['PairIdentifier', 'PairType', 'Persistence', 'Birth', 'IsFinite']
        diagram.PointArrayStatus = ['ttkVertexScalarField', 'CriticalType', 'Coordinates', 'PointIds']
        diagram.TimeArray = 'None'

        base.diagram = diagram
        return base

    @classmethod
    def get_mcp_name(cls): # token type for the MCP server
        return "persistence_diagram_embedding"

    @classmethod
    def is_unique_visualization(cls):
        return True

    @classmethod
    def unique_visualization_dimension(cls):
        return 2

    def visualize(self, renderView):
        spheres = ttk.TTKIcospheresFromPoints(Input=self.diagram)
        spheres.Radius = self.ball_radius

        spheres_display = Show(spheres, renderView, 'GeometryRepresentation')
        spheres_display.Representation = 'Surface'
        spheres_display.ColorArrayName = ['POINTS', 'PointIds']

        spheres_LUT = GetColorTransferFunction('PointIds')
        spheres_LUT.RGBPoints = self.lut
        spheres_LUT.ScalarRangeInitialized = 1.0

        spheres_display.LookupTable = spheres_LUT

        extractSurface = ExtractSurface(Input=self.diagram)

        # create a new 'Tube'
        tube = Tube(Input=extractSurface)
        tube.Radius = self.tube_radius

        tube_display = Show(tube, renderView, 'GeometryRepresentation')
        tube_display.ColorArrayName = ['POINTS', '']

    @classmethod
    def get_mcp_name(cls):
        return "persistence_diagram_embedding"

    @classmethod
    def chat_description(cls):
        return "persistence diagram embedding"
